"Копию базы каждую ночь делает Worker casualhub-rt и кладёт в хранилище R2. Пока он не выложен вместе с хранилищем, копий нет. Порядок — в README, раздел «Резервные копии».":"Копію бази щоночі робить Worker casualhub-rt і кладе в сховище R2. Поки його не викладено разом зі сховищем, копій немає. Порядок — у README, розділ «Резервні копії».",
"каждую ночь, хранятся последние {}":"щоночі, зберігаються останні {}",
"В копии все оценки, фото, тир-листы, лоты и аккаунты. Пароли, 2FA и пин-коды в ней зашифрованы ключом BACKUP_KEY, которого в хранилище нет. Входы на устройствах в копию не попадают: после восстановления все войдут заново. Файл — JSON Lines, восстановление описано в README.":"У копії всі оцінки, фото, тір-лісти, лоти й акаунти. Паролі, 2FA і пін-коди в ній зашифровано ключем BACKUP_KEY, якого у сховищі немає. Входи на пристроях у копію не потрапляють: після відновлення всі увійдуть знову. Файл — JSON Lines, відновлення описано в README.",
"Ключ BACKUP_KEY не задан: пароли, 2FA и пин-коды в копию не попадают, после восстановления их придётся сбрасывать. Как задать ключ — в README, раздел «Резервные копии».":"Ключ BACKUP_KEY не задано: паролі, 2FA і пін-коди в копію не потрапляють, після відновлення їх доведеться скидати. Як задати ключ — у README, розділ «Резервні копії».",
