"Аккаунт и всё, что лежит на сервере, удалятся сразу и навсегда: оценки в облаке, тир-листы, друзья, комментарии, реакции и сборы лотов. Вернуть нельзя. Оценки в этом браузере останутся гостевыми":"Акаунт і все, що лежить на сервері, видаляться одразу й назавжди: оцінки в хмарі, тір-лісти, друзі, коментарі, реакції та збори лотів. Повернути не можна. Оцінки в цьому браузері залишаться гостьовими",
