"Каждому досчитается опыт за то, что уже сделано на сайте: оценки, отзывы, тир-листы, друзей, реакции, комментарии и сборы лотов. Повторный запуск ничего не удваивает, но снять начисленное можно только вручную: «Опыт ±» у человека":"Кожному дорахується досвід за те, що вже зроблено на сайті: оцінки, відгуки, тір-лісти, друзів, реакції, коментарі та збори лотів. Повторний запуск нічого не подвоює, але зняти нараховане можна лише вручну: «Досвід ±» у людини",
"Начислить":"Нарахувати",
