"Звание считается по опыту, набранному за сезон. Сезон длится три месяца: в конце звания у всех сбрасываются, а итог остаётся в истории.":"Звання рахується за досвідом, набраним за сезон. Сезон триває три місяці: наприкінці звання в усіх скидаються, а підсумок залишається в історії.",
