"Так тебя видят в профиле и в списках друзей":"Так тебе бачать у профілі й у списках друзів",
"Рамку и значок видят все, кто открывает твой профиль или видит тебя в списке друзей.":"Рамку й значок бачать усі, хто відкриває твій профіль або бачить тебе в списку друзів.",
