"Цвета секторов и конфетти на победу — на твоём Колесе.":"Кольори секторів і конфеті на перемогу — на твоєму Колесі.",
"Тема задаёт цвета рядов новых тир-листов, палитру рядов и фон картинки, когда скачиваешь тир-лист.":"Тема задає кольори рядів нових тір-лістів, палітру рядів і фон картинки, коли завантажуєш тір-ліст.",
"Рофланы копятся у тех, кто вошёл в аккаунт: за оценки, отзывы, задания и всё, за что даётся опыт.":"Рофлани накопичуються в тих, хто увійшов в акаунт: за оцінки, відгуки, завдання й усе, за що дається досвід.",
"Магазин пока закрыт: он откроется вместе с уровнями.":"Магазин поки закритий: він відкриється разом із рівнями.",
"Окрасы и наряды для котика Васяна. Купленное надевается здесь же или в Настройках → «Внешний вид».":"Забарвлення й вбрання для котика Васяна. Куплене надівається тут же або в Налаштуваннях → «Зовнішній вигляд».",
"Котик Васян есть у первой десятки и у всех с 25-го уровня. Окрасы и наряды откроются, когда он появится у тебя.":"Котик Васян є в першої десятки й у всіх із 25-го рівня. Забарвлення й вбрання відкриються, коли він з’явиться в тебе.",
"Фон и курсор видишь только ты, на всех страницах сайта. Курсор — на компьютере, на телефоне его нет.":"Фон і курсор бачиш лише ти, на всіх сторінках сайту. Курсор — на комп’ютері, на телефоні його немає.",
"Заморозка спасает серию, если пропустишь день. Сейчас {} из {}; одна новая и так приходит каждую неделю.":"Заморозка рятує серію, якщо пропустиш день. Зараз {} з {}; одна нова й так приходить щотижня.",
"Рофланы копятся сами — за всё, за что на сайте даётся опыт: 1 рофлан за каждые {} опыта. Ещё — за достижения (бронза 15, серебро ещё 40, золото ещё 100, особые 30) и за звание в конце сезона (до 300 у «Величайшего»). Покупать можно только оформление и заморозки: опыт и звания за рофланы не купить.":"Рофлани накопичуються самі — за все, за що на сайті дається досвід: 1 рофлан за кожні {} досвіду. Ще — за досягнення (бронза 15, срібло ще 40, золото ще 100, особливі 30) і за звання наприкінці сезону (до 300 у «Найвеличнішого»). Купувати можна лише оформлення й заморозки: досвід і звання за рофлани не купити.",
