"Окрасы, наряды, миски, лотки и еда для котика Васяна. Купленное надевается здесь же или в Настройках → «Внешний вид». Еда открывается и сама: по одной за каждый уровень, начиная со 2-го, — купить можно раньше. Часть мисок и лотков не продаётся: их открывают достижения, некоторые — тайные.":"Забарвлення, вбрання, миски, лотки та їжа для котика Васяна. Куплене надівається тут же або в Налаштуваннях → «Зовнішній вигляд». Їжа відкривається й сама: по одній за кожен рівень, починаючи з 2-го, — купити можна раніше. Частину мисок і лотків не продають: їх відкривають досягнення, деякі — таємні.",
"Котик Васян есть у первой десятки и у всех с 25-го уровня. Окрасы, наряды, миски, лотки и еда откроются, когда он появится у тебя.":"Котик Васян є в першої десятки й у всіх із 25-го рівня. Забарвлення, вбрання, миски, лотки та їжа відкриються, коли він з’явиться в тебе.",
"Окрасы, наряды, миски, лотки и еда — для тех, у кого есть котик Васян: первая десятка и все с 25-го уровня.":"Забарвлення, вбрання, миски, лотки та їжа — для тих, у кого є котик Васян: перша десятка й усі з 25-го рівня.",
