"Мнение → «Друзья»: открой оценку друга и выбери реакцию под ней. Реакции на тир-листы друзей тоже считаются":"Думка → «Друзі»: відкрий оцінку друга й вибери реакцію під нею. Реакції на тір-лісти друзів теж рахуються",
"Под оценкой друга (Мнение → «Друзья») или под его тир-листом. Нужно от 10 знаков — короткое «ок» не засчитается":"Під оцінкою друга (Думка → «Друзі») або під його тір-лістом. Потрібно від 10 знаків — коротке «ок» не зарахується",
